Authenticate with the Fathom SDKs using API keys
import { Fathom } from 'fathom-typescript'; const fathom = new Fathom({ security: { apiKeyAuth: process.env.FATHOM_API_KEY_AUTH || "" } });
from fathom_python import models, Fathom import os fathom = Fathom(security=models.Security( api_key_auth=os.getenv("FATHOM_API_KEY_AUTH", "") ))
import { Fathom } from 'fathom-typescript'; const fathom = new Fathom({ security: { bearerAuth: "YOUR_BEARER_TOKEN" } });
from fathom_python import models, Fathom fathom = Fathom(security=models.Security( bearer_auth="YOUR_BEARER_TOKEN" ))
